// Fix: use let instead of var
for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0) // logs 0, 1, 2
}

function makeCounter() {
  let count = 0
  return {
    increment() { return ++count },
    decrement() { return --count },
    value() { return count },
  }
}

const counter = makeCounter()
counter.increment() // 1
counter.increment() // 2
counter.value()     // 2
